-- V2_128: 표준 메타 확장 — 표준 용어의 동의어·허용값·폐기 여부(ADR-0029 결정 10, DEC-OPS-312)
-- [근거] 행정안전부 공통표준용어 CSV(2025-11 판, .agent/knowledge/db-standard-constitution/artifacts/sources/
--        mois-standard-terms-20251101.csv)의 '용어 이음동의어 목록'·'허용값'·'개정구분명(폐기 또는 변경)' 열이다.
--        live 메타(meta_standard_terms)에는 이 정보가 없어 이관 도구가 동의어 후보·허용값 적합성·폐기 용어 확정
--        차단을 할 수 없었다.
-- [범위] 컬럼 추가(Expand)와 값 채우기뿐이다. 기존 열·행·키는 바꾸지 않는다. 채우는 행은 5,683개다
--        (동의어 759·허용값 5,033·폐기 5).
-- [제외] CSV 에서 같은 영문약어가 서로 다른 값으로 두 번 나오는 TXPR_NM·BZMN_NM·CONM 은 채우지 않는다 —
--        어느 쪽이 맞는지 정할 근거가 없다.
-- [무중단] NULL 허용 컬럼 둘과 DEFAULT 가 있는 NOT NULL 컬럼 하나를 더한다. 구버전 INSERT 를 깨지 않는다.
-- [공유 DB] 공유 OCI DB 적용은 별도 승인이다(ADR-0029 결정 10).

ALTER TABLE meta_standard_terms ADD COLUMN IF NOT EXISTS synonyms text;
ALTER TABLE meta_standard_terms ADD COLUMN IF NOT EXISTS allowed_values text;
ALTER TABLE meta_standard_terms ADD COLUMN IF NOT EXISTS deprecated_yn varchar(1) NOT NULL DEFAULT 'N';
ALTER TABLE meta_standard_terms ADD CONSTRAINT ck_meta_standard_terms_deprecated_yn CHECK (deprecated_yn IN ('Y', 'N'));

COMMENT ON COLUMN meta_standard_terms.synonyms IS '용어 이음동의어 목록(쉼표 구분, 공통표준 원문)';
COMMENT ON COLUMN meta_standard_terms.allowed_values IS '허용값(공통표준 원문)';
COMMENT ON COLUMN meta_standard_terms.deprecated_yn IS '폐기 여부(Y 면 새 매핑에 쓰지 않는다)';

